const extractRawText = (item) =>
  item.json.output?.[0]?.content?.[0]?.text ||
  item.json.output?.[0]?.text ||
  item.json.content?.[0]?.text ||
  item.json.text ||
  item.json.response ||
  item.json.message ||
  '';

const normalizeJobId = (url) => {
  const raw = String(url || '').trim();
  if (!raw) return '';
  const viewMatch = raw.match(/jobs\/view\/(\d+)/i);
  if (viewMatch?.[1]) return viewMatch[1];
  const currentMatch = raw.match(/(?:[?&]currentJobId=)(\d+)/i);
  if (currentMatch?.[1]) return currentMatch[1];
  return '';
};

const recoverJobIdFromHints = (company, role, hints) => {
  const companyNorm = String(company || '').trim().toLowerCase();
  const roleNorm = String(role || '').trim().toLowerCase();
  if (!companyNorm || !roleNorm || !Array.isArray(hints) || hints.length === 0) return '';

  for (const h of hints) {
    const id = String(h.jobId || '').trim() || normalizeJobId(h.url);
    if (!id) continue;

    const anchorNorm = String(h.anchorText || '').trim().toLowerCase();
    if (anchorNorm !== roleNorm) continue;

    const contextLines = String(h.context || '')
      .split('\n')
      .map((line) => line.trim().toLowerCase())
      .filter(Boolean);

    if (contextLines.some((line) => line === companyNorm)) return id;
  }

  return '';
};

// OPPORTUNITY-DEDUPE-V1 Ã¢â‚¬â€ must match Filter New CRM JobIds exactly.
const DASH_VARIANTS = /[\u2010-\u2015\u2212\u2013\u2014\u2012\u2011]/g;

const normalizeOpportunityText = (value) => {
  let s = String(value ?? '').trim();
  if (!s) return '';
  try {
    s = s.normalize('NFKD').replace(/\p{M}/gu, '');
  } catch {
    s = s.normalize('NFKD');
  }
  s = s.toLowerCase();
  s = s.replace(DASH_VARIANTS, '-');
  s = s.replace(/[^\p{L}\p{N}\s-]/gu, ' ');
  s = s.replace(/\s+/g, ' ').trim();
  return s;
};

const normalizeWorkTypeForOpportunity = (workType, location) => {
  const wt = String(workType || '').trim().toLowerCase();
  const loc = String(location || '').trim().toLowerCase();

  const hasHybrid = wt === 'hybrid' || /\bhybrid\b/.test(loc);
  const hasOnsite =
    wt === 'onsite' || wt === 'on-site' || /\bon-?site\b/.test(loc) || /\bonsite\b/.test(loc);
  const hasRemote = wt === 'remote' || /\bremote\b/.test(loc);

  if (hasHybrid) return 'hybrid';
  if (hasOnsite && !hasRemote) return 'onsite';
  if (hasRemote) return 'remote';
  if (hasOnsite) return 'onsite';
  return '';
};

const buildOpportunityKey = (company, role, location, workType) => {
  const normCompany = normalizeOpportunityText(company);
  const normRole = normalizeOpportunityText(role);
  if (!normCompany || !normRole) return '';

  const wt = normalizeWorkTypeForOpportunity(workType, location);
  if (wt === 'remote') {
    return `${normCompany}|${normRole}|remote`;
  }
  if (wt === 'hybrid' || wt === 'onsite') {
    const normLoc = normalizeOpportunityText(location);
    return `${normCompany}|${normRole}|${normLoc}|${wt}`;
  }

  const normLoc = normalizeOpportunityText(location);
  return `${normCompany}|${normRole}|${normLoc}|${wt || 'unspecified'}`;
};

const locationAllowed = (location, workType = '') => {
  const loc = String(location || '').toLowerCase().trim();
  const wt = String(workType || '').toLowerCase().trim();

  if (/relocation|relocate\s*required/.test(loc)) return false;

  if (loc.includes('bulgaria')) return true;

  if (
    loc.includes('remote europe') ||
    loc.includes('remote emea') ||
    loc.includes('emea Ã‚Â· remote') ||
    loc.includes('europe Ã‚Â· remote') ||
    loc.includes('remote worldwide') ||
    loc.includes('remote global')
  ) {
    return true;
  }

  const hasRemote = wt === 'remote' || /\bremote\b/.test(loc);
  const hasHybrid = wt === 'hybrid' || /\bhybrid\b/.test(loc);
  const hasOnsite =
    wt === 'onsite' || wt === 'on-site' || /\bon-?site\b/.test(loc) || /\bonsite\b/.test(loc);

  // Country-specific remote Ã¢â‚¬â€ pass early gate; verify after full job read
  if (hasRemote && loc.includes('Ã‚Â· remote')) return true;

  // Unqualified remote Ã¢â‚¬â€ pass early gate
  if (hasRemote && !hasHybrid && !hasOnsite) return true;

  if (hasHybrid && !loc.includes('bulgaria')) return false;

  if (hasOnsite && !loc.includes('bulgaria')) return false;

  if (!hasRemote && !loc.includes('bulgaria')) {
    const nonRemoteCountries = [
      'united kingdom', 'netherlands', 'spain', 'france', 'italy',
      'germany', 'portugal', 'switzerland', 'united states',
    ];
    if (nonRemoteCountries.some((c) => loc.includes(c))) return false;
  }

  return true;
};

const locationRejectReason = (location, workType, allowed) => {
  if (allowed) return '';
  const loc = String(location || '').toLowerCase().trim();
  const wt = String(workType || '').toLowerCase().trim();
  if (/relocation|relocate\s*required/.test(loc)) return 'Relocation required.';
  if ((/\bhybrid\b/.test(loc) || wt === 'hybrid') && !loc.includes('bulgaria')) {
    return 'Hybrid outside Bulgaria rejected.';
  }
  if ((/\bon-?site\b/.test(loc) || /\bonsite\b/.test(loc) || wt === 'onsite') && !loc.includes('bulgaria')) {
    return 'On-site outside Bulgaria rejected.';
  }
  return 'Non-remote location outside Bulgaria rejected.';
};

const looksFakeCompany = (company, role) => {
  const c = String(company || '').toLowerCase().trim();
  const r = String(role || '').toLowerCase().trim();

  if (!c) return true;
  if (c === r) return true;

  const blockedExactCompanies = [
    'remote',
    'hybrid',
    'onsite',
    'on-site',
    'on site',
    'full-time',
    'part-time',
    'contract',
    'temporary',
    'internship'
  ];

  if (blockedExactCompanies.includes(c)) return true;

  if (
    c.includes('connections') ||
    c.includes('install linkedin widgets') ||
    c.includes('see all jobs') ||
    c.includes('actively recruiting') ||
    c.includes('actively reviewing applicants') ||
    c.includes('fast growing') ||
    c.includes('promoted by hirer') ||
    c.includes('responses managed off linkedin')
  ) return true;

  const roleWords = [
    'manager', 'director', 'head', 'chief', 'vp',
    'operations', 'revenue', 'strategy', 'business',
    'lead', 'program', 'product', 'commercial', 'revops'
  ];

  const companyLooksLikeRole = roleWords.some(w => c.includes(w));
  if (companyLooksLikeRole) return true;

  return false;
};

const normalizeEmailItems = $('Normalize Email Content').all();

const getEmailFields = (index) => {
  const emailMeta = normalizeEmailItems[index]?.json || {};
  return {
    EmailId: emailMeta.EmailId || '',
    ThreadId: emailMeta.ThreadId || '',
    EmailReceived: emailMeta.EmailReceived || '',
    EmailSubject: emailMeta.EmailSubject || '',
    EmailSnippet: emailMeta.EmailSnippet || '',
    TestMode: emailMeta.TestMode ?? '',
    TestLabelUsed: emailMeta.TestLabelUsed ?? '',
    GmailLabels: emailMeta.GmailLabels ?? '',
  };
};

const inferWorkType = (text) => {
  const t = String(text || '').toLowerCase();
  if (/\bremote\b/.test(t)) return 'Remote';
  if (/\bhybrid\b/.test(t)) return 'Hybrid';
  if (/\b(on-?site|on site)\b/.test(t)) return 'Onsite';
  return '';
};

const isMissingLocation = (value) => {
  const v = String(value || '').trim();
  return !v || v.toLowerCase() === 'not specified';
};

const pickLocationLineFromContext = (text, role = '', company = '') => {
  const roleNorm = String(role || '').trim().toLowerCase();
  const companyNorm = String(company || '').trim().toLowerCase();
  const lines = String(text || '')
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean);

  const skipContextLine = (line) => {
    if (!line) return true;
    const lower = line.toLowerCase();
    if (roleNorm && lower === roleNorm) return true;
    if (companyNorm && lower === companyNorm) return true;
    if (/^(apply|save|easy apply|full-time|part-time|promoted|similar jobs|view job|see all jobs)$/i.test(line)) return true;
    if (/^\d+ (connection|mutual)/i.test(line)) return true;
    if (/^(remote|hybrid|on-?site|on site)$/i.test(line)) return true;
    if (/connections? on linkedin/i.test(line)) return true;
    return false;
  };

  for (const line of lines) {
    if (skipContextLine(line)) continue;
    if (/[Ã‚Â·Ã¢â‚¬Â¢]\s*(remote|hybrid|on-?site|on site)\b/i.test(line)) return line;
    if (/,/.test(line) && line.length >= 5 && line.length <= 120 && /[a-z]/i.test(line)) return line;
  }

  for (const line of lines) {
    if (skipContextLine(line)) continue;
    if (line.length < 3 || line.length > 80) continue;
    if (!/^[\p{L}\p{M}\s'.-]+$/u.test(line)) continue;
    if (/\b(manager|director|head|chief|vp|founder|co-founder|coo|ceo|operations)\b/i.test(line)) continue;
    return line;
  }

  return '';
};

const parseLocationFromText = (text, role = '', company = '') => {
  const t = String(text || '');
  const lower = t.toLowerCase();
  const workType = inferWorkType(t);

  if (/remote europe/.test(lower)) return 'Remote Europe';
  if (/remote emea/.test(lower)) return 'Remote EMEA';
  if (/remote worldwide|remote global/.test(lower)) return 'Remote Worldwide';

  const countries = [
    ['bulgaria', 'Bulgaria'],
    ['united kingdom', 'United Kingdom'],
    ['portugal', 'Portugal'],
    ['italy', 'Italy'],
    ['france', 'France'],
    ['switzerland', 'Switzerland'],
    ['netherlands', 'Netherlands'],
    ['germany', 'Germany'],
    ['spain', 'Spain'],
    ['united states', 'United States'],
  ];

  for (const [needle, label] of countries) {
    if (lower.includes(needle)) {
      return workType ? `${label} Ã‚Â· ${workType}` : label;
    }
  }

  const picked = pickLocationLineFromContext(t, role, company);
  if (picked) return picked;

  return 'Not specified';
};

const resolveCardLocation = (rawLocation, contextText = '', role = '', company = '') => {
  const direct = String(rawLocation || '').trim();
  if (!isMissingLocation(direct)) return direct;

  const context = String(contextText || '').trim();
  if (!context) return 'Not specified';

  return parseLocationFromText(context, role, company);
};

const buildDeterministicJobs = (content) => {
  const hints = content.JobUrlHints || [];
  const subjectHint = content.SubjectJobHint || {};
  const jobs = [];

  const skipLine = (line, role) =>
    !line ||
    line === role ||
    /^(apply|save|easy apply|full-time|part-time|promoted|similar jobs|view job|see all jobs)$/i.test(line) ||
    /^(remote|hybrid|on-?site|on site)$/i.test(line) ||
    /^\d+ (connection|mutual)/i.test(line);

  for (const hint of hints) {
    const url = String(hint.url || '').trim();
    if (!url) continue;

    const role = String(hint.anchorText || subjectHint.role || '').trim();
    const contextLines = String(hint.context || '')
      .split('\n')
      .map((l) => l.trim())
      .filter(Boolean);

    let company = '';
    if (hints.length === 1 && subjectHint.company) {
      company = String(subjectHint.company).trim();
    }
    if (!company) {
      company = contextLines.find((l) => !skipLine(l, role) && l.length <= 80) || '';
    }

    if (!company || !role) continue;

    jobs.push({
      company,
      role,
      location: resolveCardLocation('', hint.context, role, company),
      work_type: inferWorkType(hint.context),
      url,
    });
  }

  if (jobs.length === 0 && hints.length === 1 && subjectHint.company && subjectHint.role) {
    jobs.push({
      company: String(subjectHint.company).trim(),
      role: String(subjectHint.role).trim(),
      location: resolveCardLocation('', content.EmailText || '', String(subjectHint.role || '').trim(), String(subjectHint.company || '').trim()),
      work_type: inferWorkType(content.EmailText || ''),
      url: String(hints[0].url || '').trim(),
    });
  }

  return jobs;
};

const buildFallbackItem = (emailFields, extractionError = 'AI Extract returned []') => ({
  json: {
    ...emailFields,
    Source: 'LinkedIn Email',
    Status: 'Rejected',
    Apply: 'NO',
    Recommendation: 'NO',
    Apply: 'NO',
    Reason: 'AI Extract returned no job cards',
    RejectReason: 'AI Extract returned no job cards',
    MainRisk: 'No job card parsed from email',
    Risk: 'No job card parsed from email',
    Role: '',
    Company: '',
    Location: '',
    URL: '',
    JobUrl: '',
    JobId: '',
    WorkType: '',
    DedupeKey: emailFields.EmailId || '',
    ExtractionStatus: 'NO_JOB_CARD',
    ExtractionError: extractionError,
    PipelineStage: 'NO_JOB_CARD',
    LocationAllowed: true,
    LocationRejectReason: 'AI Extract returned no job cards',
    Notes: '',
    ParseError: '',
  },
});

const output = [];
const seenJobIds = new Set();
const seenNoIdCompositeKeys = new Set();
const seenOpportunityKeys = new Set();
const inputItems = $input.all();

for (let inputIndex = 0; inputIndex < inputItems.length; inputIndex++) {
  const item = inputItems[inputIndex];
  const emailFields = getEmailFields(inputIndex);
  const raw = extractRawText(item);

  let clean = String(raw)
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const firstBracket = clean.indexOf('[');
  const lastBracket = clean.lastIndexOf(']');

  if (firstBracket !== -1 && lastBracket !== -1 && lastBracket > firstBracket) {
    clean = clean.slice(firstBracket, lastBracket + 1);
  }

  let parsed;

  try {
    parsed = JSON.parse(clean);
  } catch (e) {
    output.push(buildFallbackItem(emailFields, 'AI Extract returned invalid JSON'));
    continue;
  }

  const jobs = Array.isArray(parsed) ? parsed : (parsed.jobs || []);

  let jobList = jobs;
  if (jobList.length === 0) {
    const content = normalizeEmailItems[inputIndex]?.json || {};
    jobList = buildDeterministicJobs(content);
    if (jobList.length === 0) {
      output.push(buildFallbackItem(emailFields));
      continue;
    }
  }

  let addedForEmail = false;

  for (const j of jobList) {
    if (!j || !j.company || !j.role) continue;
    if (looksFakeCompany(j.company, j.role)) continue;

    const company = String(j.company || '').trim();
    const role = String(j.role || '').trim();
    const url = String(j.url || '').trim();
    const emailContent = normalizeEmailItems[inputIndex]?.json || {};
    const jobUrlHints = emailContent.JobUrlHints || [];
    const hint = jobUrlHints.find(
      (h) => String(h.url || '').trim() === url,
    );
    const contextText = hint?.context || emailContent.EmailText || '';
    const location = resolveCardLocation(j.location, contextText, role, company);
    const workType = String(j.work_type || '').trim();

    let jobId = normalizeJobId(url);
    if (!jobId) {
      jobId = recoverJobIdFromHints(company, role, jobUrlHints);
    }

    let dedupeKey;
    if (jobId) {
      if (seenJobIds.has(jobId)) continue;
      seenJobIds.add(jobId);
      dedupeKey = jobId;
    } else {
      const compositeKey = `${company}|${role}|${location}`.toLowerCase();
      if (!compositeKey || compositeKey === '||') continue;
      if (seenNoIdCompositeKeys.has(compositeKey)) continue;
      seenNoIdCompositeKeys.add(compositeKey);
      dedupeKey = compositeKey;
    }

    const opportunityKey = buildOpportunityKey(company, role, location, workType);
    if (opportunityKey && seenOpportunityKeys.has(opportunityKey)) continue;
    if (opportunityKey) seenOpportunityKeys.add(opportunityKey);

    addedForEmail = true;

    const allowed = locationAllowed(location, workType);

    output.push({
      json: {
        ...emailFields,
        Role: role,
        Company: company,
        JobId: jobId,
        Location: location,
        WorkType: workType,
        URL: url,
        LocationAllowed: allowed,
        LocationRejectReason: locationRejectReason(location, workType, allowed),
        Source: 'LinkedIn',
        Status: 'New',
        Notes: '',
        ParseError: '',
        DedupeKey: dedupeKey
      }
    });
  }

  if (!addedForEmail) {
    output.push(buildFallbackItem(emailFields, 'AI Extract returned no valid job cards'));
  }
}

return output;

// Commit 2B Ã¢â‚¬â€ sheet JobId + OpportunityKey dedupe (keep in sync with Parse Job Cards).
// Preserve pairedItem: filter $input (Parse Job Cards items); sheet via $('Read CRM Existing JobIds').
const normalizeSheetJobId = (value) => {
  const s = String(value ?? '').trim();
  if (!s || !/^\d+$/.test(s)) return '';
  return s;
};

const normalizeJobIdFromUrl = (url) => {
  const raw = String(url || '').trim();
  if (!raw) return '';
  const viewMatch = raw.match(/jobs\/view\/(\d+)/i);
  if (viewMatch?.[1]) return viewMatch[1];
  const currentMatch = raw.match(/(?:[?&]currentJobId=)(\d+)/i);
  if (currentMatch?.[1]) return currentMatch[1];
  return '';
};

const extractJobIdFromRow = (row) => {
  const j = row?.json || row || {};
  const fromJobId = normalizeSheetJobId(j.JobId);
  if (fromJobId) return fromJobId;
  const fromDedupe = normalizeSheetJobId(j.DedupeKey);
  if (fromDedupe) return fromDedupe;
  return normalizeJobIdFromUrl(j.URL || j.Url || j.url);
};

const extractJobIdFromParsed = (j) => {
  const fromJobId = normalizeSheetJobId(j.JobId);
  if (fromJobId) return fromJobId;
  const fromDedupe = normalizeSheetJobId(j.DedupeKey);
  if (fromDedupe) return fromDedupe;
  return normalizeJobIdFromUrl(j.URL || j.Url || j.url);
};

// OPPORTUNITY-DEDUPE-V1 Ã¢â‚¬â€ must match Parse Job Cards exactly.
const DASH_VARIANTS = /[\u2010-\u2015\u2212\u2013\u2014\u2012\u2011]/g;

const normalizeOpportunityText = (value) => {
  let s = String(value ?? '').trim();
  if (!s) return '';
  try {
    s = s.normalize('NFKD').replace(/\p{M}/gu, '');
  } catch {
    s = s.normalize('NFKD');
  }
  s = s.toLowerCase();
  s = s.replace(DASH_VARIANTS, '-');
  s = s.replace(/[^\p{L}\p{N}\s-]/gu, ' ');
  s = s.replace(/\s+/g, ' ').trim();
  return s;
};

const normalizeWorkTypeForOpportunity = (workType, location) => {
  const wt = String(workType || '').trim().toLowerCase();
  const loc = String(location || '').trim().toLowerCase();

  const hasHybrid = wt === 'hybrid' || /\bhybrid\b/.test(loc);
  const hasOnsite =
    wt === 'onsite' || wt === 'on-site' || /\bon-?site\b/.test(loc) || /\bonsite\b/.test(loc);
  const hasRemote = wt === 'remote' || /\bremote\b/.test(loc);

  if (hasHybrid) return 'hybrid';
  if (hasOnsite && !hasRemote) return 'onsite';
  if (hasRemote) return 'remote';
  if (hasOnsite) return 'onsite';
  return '';
};

const buildOpportunityKey = (company, role, location, workType) => {
  const normCompany = normalizeOpportunityText(company);
  const normRole = normalizeOpportunityText(role);
  if (!normCompany || !normRole) return '';

  const wt = normalizeWorkTypeForOpportunity(workType, location);
  if (wt === 'remote') {
    return `${normCompany}|${normRole}|remote`;
  }
  if (wt === 'hybrid' || wt === 'onsite') {
    const normLoc = normalizeOpportunityText(location);
    return `${normCompany}|${normRole}|${normLoc}|${wt}`;
  }

  const normLoc = normalizeOpportunityText(location);
  return `${normCompany}|${normRole}|${normLoc}|${wt || 'unspecified'}`;
};

const extractOpportunityKeyFromRecord = (j) =>
  buildOpportunityKey(
    j.Company,
    j.Role,
    j.Location,
    j.WorkType || j.work_type || '',
  );

const parsedItems = $input.all();
const sheetRows = $('Read CRM Existing JobIds').all();

const existingJobIds = new Set();
const existingOpportunityKeys = new Set();
for (const row of sheetRows) {
  const j = row?.json || row || {};
  const id = extractJobIdFromRow(row);
  if (id) existingJobIds.add(id);
  const oppKey = extractOpportunityKeyFromRecord(j);
  if (oppKey) existingOpportunityKeys.add(oppKey);
}

const passed = [];
for (const item of parsedItems) {
  const j = item.json || {};
  const jobId = extractJobIdFromParsed(j);
  const oppKey = extractOpportunityKeyFromRecord(j);

  if (jobId && existingJobIds.has(jobId)) continue;
  if (oppKey && existingOpportunityKeys.has(oppKey)) continue;

  passed.push({ ...item });
}

return passed;

// DEV-ONLY: cap extracted job cards per workflow run when TestMode=true.
// TestMaxResults limits Gmail messages; MaxJobCards limits cards after Parse Job Cards.
// Preserve pairedItem on every output item so $('Parse Job Cards').item works downstream.
const asBool = (v) => v === true || v === 'true' || v === 1;
const devConfig = $('DEV Config - Gmail Input Selection').first().json || {};

if (!asBool(devConfig.TestMode)) {
  return $input.all();
}

const maxJobCards = Number(devConfig.MaxJobCards);
if (!Number.isFinite(maxJobCards) || maxJobCards < 1) {
  return $input.all();
}

const cap = Math.max(1, Math.floor(maxJobCards));
const staticData = $getWorkflowStaticData('global');
const runKey = String($execution.id || 'dev');

if (staticData.devJobCardCapRunKey !== runKey) {
  staticData.devJobCardCapRunKey = runKey;
  staticData.devJobCardCapCount = 0;
}

if (staticData.devJobCardCapCount >= cap) {
  return [];
}

const passed = [];
for (const item of $input.all()) {
  if (staticData.devJobCardCapCount >= cap) break;
  staticData.devJobCardCapCount += 1;
  passed.push({
    ...item,
    json: {
      ...item.json,
      DevJobCardCapApplied: true,
      DevJobCardCapLimit: cap,
      DevJobCardCapIndex: staticData.devJobCardCapCount,
    },
  });
}

return passed;

// DEV-ONLY: set to true to inject a low-fit mock job and bypass Gmail parse output.
// Must remain false for normal DEV/production runs.
const DEV_TEST_MODE_ENABLED = false;

if (!DEV_TEST_MODE_ENABLED) {
  return $input.all();
}

return [
  {
    json: {
      EmailId: 'test-low-fit-email',
      ThreadId: 'test-low-fit-thread',
      EmailReceived: String(Date.now()),
      EmailSubject: 'TEST low fit job',
      EmailSnippet: 'Entry-level customer support role in the United States, on-site.',
      Role: 'Junior Customer Support Agent',
      Company: 'Test Company',
      Location: 'United States Ã‚Â· On-site',
      URL: 'https://example.com/test-job',
      JobUrl: 'https://example.com/test-job',
      JobId: '',
      WorkType: 'Onsite',
      Source: 'TEST',
      Status: 'New',
      Notes: '',
      ParseError: '',
      DedupeKey: 'test-low-fit-job',
      LocationAllowed: false,
      LocationRejectReason: 'Country-specific or non-Bulgaria location rejected.',
      DevTestMode: true,
      DevTestCase: 'LOW_PREVIEW_SCORE',
    },
  },
];

const url = String($json.URL || '').trim();

const TITLE_LANG_NAMES = [
  'spanish', 'german', 'french', 'dutch', 'italian', 'portuguese',
  'polish', 'czech', 'hungarian', 'romanian', 'greek', 'swedish',
  'norwegian', 'danish', 'finnish', 'russian', 'ukrainian', 'arabic',
  'chinese', 'mandarin', 'cantonese', 'japanese', 'korean', 'hindi',
  'turkish', 'hebrew', 'slovak', 'croatian', 'serbian', 'vietnamese',
  'thai', 'indonesian', 'malay', 'tagalog', 'flemish', 'catalan',
];

const LANG_TITLE_REJECT = 'Mandatory non-English/non-Bulgarian language indicated in title.';

const isBlockedLanguagePhrase = (phrase) => {
  const t = String(phrase || '').toLowerCase().trim();
  if (!t) return false;
  if (t === 'english' || t === 'bulgarian') return false;
  if (TITLE_LANG_NAMES.includes(t)) return true;
  for (const lang of TITLE_LANG_NAMES) {
    if (new RegExp(`^${lang}\\s+(speaker|speaking|fluent|native)\\b`).test(t)) return true;
    if (new RegExp(`\\b${lang}\\s+(speaker|speaking|fluent|native)\\b`).test(t)) return true;
    if (new RegExp(`\\b(speaker|speaking|fluent|native)\\s+${lang}\\b`).test(t)) return true;
  }
  return false;
};

const languageInTitleBlocked = (role) => {
  const title = String(role || '').trim();
  if (!title) return false;

  for (const paren of title.match(/\(([^)]+)\)/g) || []) {
    if (isBlockedLanguagePhrase(paren.slice(1, -1))) return true;
  }

  const dashParts = title.split(/\s+[-\u2013\u2014]\s+/);
  for (let i = 1; i < dashParts.length; i++) {
    if (isBlockedLanguagePhrase(dashParts[i])) return true;
  }

  const lower = title.toLowerCase();
  for (const lang of TITLE_LANG_NAMES) {
    if (new RegExp(`\\b${lang}\\s+(speaker|speaking|fluent|native)\\b`).test(lower)) return true;
  }

  return false;
};

