    /\bgesch[aÃƒÂ¤]ftsleitung\b/i,
    /\bkaufm[aÃƒÂ¤]nnisch(?:er|e|r)?\s+leiter(in)?\b/i,
    /\btechnisch(?:er|e|r)?\s+leiter(in)?\b/i,
    /\boperativ(?:er|e|r)?\s+leiter(in)?\b/i,
  ];

  return patterns.some((re) => re.test(title));
};

