  /\bassistant to\b/,
  /\bassistant\b/,
  /\bcoordinator\b/,
  /\badministrator\b/,
  /\boffice of\b/,
];

const hasExecOpsFloorExclusion = (normalizedRole) =>
  EXEC_OPS_FLOOR_EXCLUSIONS.some((pattern) => pattern.test(normalizedRole));

const EXEC_OPS_FLOOR_PREFIX =
  '(?:(?:deputy|associate|regional|global|emea|group|acting) )?';

const EXEC_OPS_FLOOR_NAMED_FAMILIES = [
  'business support and operations director',
  'transformation director',
  'business operations director',
  'commercial operations director',
  'gtm operations director',
  'go to market operations director',
  'strategy and operations director',
];

const EXEC_OPS_FLOOR_GENERIC_FAMILIES = [
  'operations director',
  'director of operations',
];

const EXEC_OPS_BLOCKED_FUNCTION_PREFIXES = [
  'it',
  'hr',
  'human resources',
  'sales',
  'finance',
  'financial',
  'legal',
  'marketing',
  'product',
  'engineering',
