const escapeRegExp = (value) =>
  String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const hasBlockedOpsFunctionPrefix = (normalizedRole) =>
  EXEC_OPS_BLOCKED_FUNCTION_PREFIXES.some((fn) => {
    const escaped = escapeRegExp(fn);
    return (
      new RegExp(`\\b${escaped} operations director\\b`).test(normalizedRole) ||
      new RegExp(`\\bdirector of ${escaped} operations\\b`).test(normalizedRole)
    );
  });

const matchesExecOpsFloorAllowlist = (normalizedRole) => {
  const namedPatterns = EXEC_OPS_FLOOR_NAMED_FAMILIES.map(
    (family) => new RegExp(`^${EXEC_OPS_FLOOR_PREFIX}${escapeRegExp(family)}$`),
  );

  if (namedPatterns.some((pattern) => pattern.test(normalizedRole))) {
    return true;
  }

  if (hasBlockedOpsFunctionPrefix(normalizedRole)) {
    return false;
  }

  return EXEC_OPS_FLOOR_GENERIC_FAMILIES.some((family) =>
    new RegExp(`^${EXEC_OPS_FLOOR_PREFIX}${escapeRegExp(family)}$`).test(normalizedRole),
  );
};

const looksLikeLocationDecision = (text) => {
