  if (t === 'string' || t === 'number' || t === 'boolean') return String(v).trim();
  if (t === 'object') {
    if (v._ != null) return String(v._).trim();
    if (v['#text'] != null) return String(v['#text']).trim();
    if (v.text != null) return String(v.text).trim();
    try { return JSON.stringify(v); } catch { return EMPTY; }
