const isLocationRelatedHardBlocker = (ai) => {
  const risk = String(ai.biggest_risk || '').toLowerCase();
  const fit = String(ai.location_fit || '').toUpperCase();
  const locationRisk = /relocation|relocate required|must (reside|live|be based|be located)|residents only|work authorization|work permit|visa required|based in (?!bulgaria)|on-site outside|onsite outside|hybrid outside|outside bulgaria|country-specific work authorization|must be based in/.test(risk);
  if (locationRisk) return true;
  if (fit === 'MISMATCH' && /location|residen|relocation|authorization|relocate|based in|on-site|onsite|hybrid/.test(risk)) return true;
  return false;
};

const isStage1HardEligibilityReject = (ai) => {
  const apply = String(ai.apply || '').trim().toUpperCase();
  const decision = String(ai.final_decision || '').trim().toUpperCase();
  if (apply !== 'NO' || decision !== 'REJECT') return false;

  const risk = String(ai.biggest_risk || '').toLowerCase();
  if (!risk.trim()) return false;

  const isLanguageBlocker =
    (/\b(c1|c2|b2\+?|fluent|native|mandatory|essential|required)\b/.test(risk)
      && /\b(german|french|dutch|italian|spanish|portuguese|language)\b/.test(risk))
    || /language.*(c1|c2|essential|mandatory|fluent|required)/.test(risk)
    || /(c1|c2|essential|mandatory|fluent|required).*language/.test(risk);

  const isTravelBlocker =
    /travel.*(>\s*20\s*%|greater than 20|more than 20)/.test(risk)
    || /(>\s*20\s*%|greater than 20%|more than 20%).*travel/.test(risk);

  const isTimezoneBlocker =
    /time\s*zone|timezone|working hours.*incompatible|hours incompatible/.test(risk);

  const isPostingLanguageBlocker =
    /posting.*(written|language).*(required|mandatory|essential)/.test(risk)
    || /(written|language).*(other than english|non-english|non-bulgarian)/.test(risk);

  return isLanguageBlocker || isTravelBlocker || isTimezoneBlocker
    || isLocationRelatedHardBlocker(ai) || isPostingLanguageBlocker;
};

