    DedupeKey: original.DedupeKey && original.DedupeKey !== '||'
      ? original.DedupeKey
      : (
          ai.dedupe_key ||
          ai.job_id ||
          original.JobId ||
          `${original.Company || ai.company || ''}|${original.Role || ai.role || ''}|${ai.location || original.Location || ''}`.toLowerCase()
        )
  }
};

// Verified score reject only — runs on Check Verified Score Threshold FALSE branch.
const threshold = Number($json.VerifiedScoreThreshold ?? 7);
const score = Number($json.VerifiedScore);

if ($json.auto_reject_reason === 'VERIFIED_PARSE_ERROR' || $json.VerifiedParseError === true) {
  return { json: $json };
}

if (Number.isFinite(score) && score >= threshold) {
  return { json: $json };
}

const reason = 'VerifiedScore missing or below threshold.';

return {
