const MIN_FULL_JOB_TEXT = 200;
const MAX_FULL_JOB_TEXT = 15000;

const decodeHtml = (s) =>
  String(s || "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">");

const stripTags = (html) =>
  String(html || "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<!--[\s\S]*?-->/g, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const isJobPostingType = (value) => {
  if (value === "JobPosting") return true;
  if (Array.isArray(value)) return value.includes("JobPosting");
  return false;
};

const extractJsonLdJobPostingDescription = (html) => {
  const blocks =
    String(html || "").match(
      /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi,
    ) || [];

  for (const block of blocks) {
    const inner = block.replace(/^<script[^>]*>/i, "").replace(/<\/script>$/i, "").trim();
    try {
      const parsed = JSON.parse(inner);
      const nodes = Array.isArray(parsed) ? parsed : [parsed];
      for (const node of nodes) {
        const graph = Array.isArray(node?.["@graph"]) ? node["@graph"] : [];
        const candidates = [node, ...graph];
        for (const item of candidates) {
          if (!isJobPostingType(item?.["@type"])) continue;
          const desc = item?.description;
          if (desc && String(desc).trim().length > 80) {
            return decodeHtml(stripTags(String(desc)));
          }
        }
      }
    } catch {
      // try next block
    }
  }
  return "";
};

const extractShowMoreMarkup = (html) => {
  const raw = String(html || "");
  const patterns = [
    /class="[^"]*show-more-less-html__markup[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /show-more-less-html__markup[^>]*>([\s\S]*?)<\/div>/i,
  ];
  for (const pattern of patterns) {
    const match = raw.match(pattern);
    if (match?.[1]) {
      const text = decodeHtml(stripTags(match[1]));
      if (text.length >= MIN_FULL_JOB_TEXT) return text;
    }
  }
  return "";
};

const extractGuestDescriptionRich = (html) => {
  const raw = String(html || "");
  const patterns = [
    /class="[^"]*description__text[^"]*description__text--rich[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /description__text--rich[^>]*>([\s\S]*?)<\/div>/i,
  ];
  for (const pattern of patterns) {
    const match = raw.match(pattern);
    if (match?.[1]) {
      const text = decodeHtml(stripTags(match[1]));
      if (text.length >= MIN_FULL_JOB_TEXT) return text;
    }
  }
  return "";
};

const extractLinkedInDescription = (html) => {
  const jsonLd = extractJsonLdJobPostingDescription(html);
  if (jsonLd.length >= MIN_FULL_JOB_TEXT) return jsonLd;

  const showMore = extractShowMoreMarkup(html);
  if (showMore.length >= MIN_FULL_JOB_TEXT) return showMore;

  const guestRich = extractGuestDescriptionRich(html);
  if (guestRich.length >= MIN_FULL_JOB_TEXT) return guestRich;

  return decodeHtml(stripTags(html));
};

const looksLikeHardBlock = (html, text) => {
  const h = String(html || "").toLowerCase();
  const t = String(text || "").toLowerCase();
  if (h.includes("authwall")) return true;
  if (t.includes("sign in to linkedin")) return true;
  if (t.length < 80 && /login|authwall/.test(h)) return true;
  return false;
};

const CLOSED_POSTING_PATTERNS = [
  /no longer accepting applications/i,
  /this job is no longer accepting applications/i,
  /applications are closed/i,
  /position has been filled/i,
  /job has expired/i,
  /job no longer available/i,
  /closed-job__flavor--closed/i,
];

const isPostingClosedText = (text) => {
  const raw = String(text || "").trim();
  if (!raw) return false;
  return CLOSED_POSTING_PATTERNS.some((re) => re.test(raw));
};

const CLOSED_REJECT_REASON = 'Closed';

const POSTING_NOT_FOUND_HTTP = new Set([404, 410]);

const resolveHttpStatusCode = (json) => {
  const direct = Number(json?.statusCode || 0);
  if (direct >= 400) return direct;
  const err = json?.error || {};
  const fromErr = Number(err.httpCode || err.statusCode || 0);
  if (fromErr >= 400) return fromErr;
  const msg = String(err.message || json?.message || '');
  const m = msg.match(/\b(404|410)\b/);
  if (m) return Number(m[1]);
  return direct || fromErr || 0;
};

const isPostingNotFoundHttp = (statusCode) => POSTING_NOT_FOUND_HTTP.has(Number(statusCode));

const upstream = $("Normalize AI Evaluation").item?.json || {};
const jobId = String(upstream.JobId || $json.JobId || "").trim();
const statusCode = resolveHttpStatusCode($json);
const html =
  typeof $json.data === "string"
    ? $json.data
    : typeof $json.body === "string"
      ? $json.body
      : typeof $json === "string"
        ? $json
        : "";

let enrichmentError = "";
let fullJobText = "";

if (!jobId && !String(upstream.URL || $json.URL || "").trim()) {
  enrichmentError = "Missing JobId and URL";
} else if (statusCode >= 400) {
  enrichmentError = `HTTP ${statusCode}`;
} else if (!String(html).trim()) {
  enrichmentError = "Empty response";
} else {
  fullJobText = extractLinkedInDescription(html).slice(0, MAX_FULL_JOB_TEXT);
  const stripped = stripTags(html);
  if (fullJobText.trim().length < MIN_FULL_JOB_TEXT) {
    enrichmentError = looksLikeHardBlock(html, stripped)
      ? "Auth wall / login page"
      : "No description block found";
  }
}

const enrichmentStatus =
  fullJobText.trim().length >= MIN_FULL_JOB_TEXT && !enrichmentError ? "OK" : "FAILED";

const strippedHtmlText = String(html).trim() ? stripTags(html) : '';
const postingClosedConfirmed =
  isPostingNotFoundHttp(statusCode) ||
  isPostingClosedText(html) ||
  isPostingClosedText(strippedHtmlText) ||
  isPostingClosedText(fullJobText);

return {
  json: {
    ...upstream,
    FullJobText: fullJobText.trim(),
    FullJobTextLength: fullJobText.trim().length,
    EnrichmentStatus: enrichmentStatus,
    EnrichmentError: enrichmentStatus === "OK" ? "" : enrichmentError || "Extraction failed",
    PostingClosedConfirmed: postingClosedConfirmed,
    PostingClosedRejectReason: postingClosedConfirmed ? CLOSED_REJECT_REASON : "",
  },
};

const MIN_FULL_JOB_TEXT = 200;
const TRAVEL_LIMIT = 20;

const TRAVEL_CTX = /\b(travel|travelling|traveling|on[- ]site|on the road)\b/i;
const SOFT_TRAVEL = /\b(occasional|optional|preferred|nice to have|highly desirable|desirable|a plus|ideally|willingness to|willing to)\b/i;
const MANDATORY_TRAVEL = /\b(required|as required|must|mandatory|essential|need to|expected to|will be required|minimum|at least)\b/i;

const parseTravelPercentMax = (chunk) => {
  const c = String(chunk || '').replace(/[Ã¢â‚¬â€œÃ¢â‚¬â€]/g, '-');
  let m = c.match(/(\d{1,2})\s*-\s*(\d{1,2})\s*%/);
  if (m) {
    const lo = parseInt(m[1], 10);
    const hi = parseInt(m[2], 10);
    return { max: Math.max(lo, hi), label: `${lo}-${hi}%` };
  }
  m = c.match(/up\s+to\s+(\d{1,2})\s*%/i);
  if (m) return { max: parseInt(m[1], 10), label: `up to ${m[1]}%` };
  m = c.match(/(?:minimum|min(?:imum)?|at least)\s+(\d{1,2})\s*%/i);
  if (m) return { max: parseInt(m[1], 10), label: `minimum ${m[1]}%` };
  m = c.match(/(\d{1,2})\s*%\s*\+/i);
  if (m) return { max: parseInt(m[1], 10), label: `${m[1]}%+` };
  m = c.match(/(\d{1,2})\s*%/);
  if (m) return { max: parseInt(m[1], 10), label: `${m[1]}%` };
  return null;
};

const isExplicitMandatoryTravel = (chunk) => {
  if (MANDATORY_TRAVEL.test(chunk)) return true;
  if (/\d{1,2}\s*%\+?\s*travel/i.test(chunk)) return true;
  if (/\btravel\b[^.]{0,80}\b(required|as required|mandatory|must)\b/i.test(chunk)) return true;
  if (/\b(required|as required|mandatory|must|minimum|at least)\b[^.]{0,80}\btravel\b/i.test(chunk)) return true;
  return false;
};

const detectMandatoryTravelBlock = (fullJobText) => {
  const text = String(fullJobText || '').trim();
  if (text.length < MIN_FULL_JOB_TEXT) return { blocked: false, reason: '', percentMax: '' };

  const chunks = [text, ...text.split(/[.;\n]/).map((c) => c.trim()).filter((c) => c.length >= 10)];
  for (const chunk of chunks) {
    if (!TRAVEL_CTX.test(chunk)) continue;
    if (/\b(?:travel|travelling|traveling)\b[^.]{0,100}\bmay\s+be\s+required\b/i.test(chunk)) continue;

    const parsed = parseTravelPercentMax(chunk);
    if (!parsed) continue;
    if (parsed.max <= TRAVEL_LIMIT) continue;
    if (SOFT_TRAVEL.test(chunk) && !isExplicitMandatoryTravel(chunk)) continue;
    if (!isExplicitMandatoryTravel(chunk)) continue;

    return {
      blocked: true,
      reason: `Mandatory travel above 20%: ${parsed.label}`,
      percentMax: String(parsed.max),
    };
  }

  return { blocked: false, reason: '', percentMax: '' };
};

const fullJobText = String($json.FullJobText || '').trim();
const enrichmentOk =
  String($json.EnrichmentStatus || '') === 'OK' && fullJobText.length >= MIN_FULL_JOB_TEXT;
const block = enrichmentOk
  ? detectMandatoryTravelBlock(fullJobText)
  : { blocked: false, reason: '', percentMax: '' };

return {
  json: {
    ...$json,
    MandatoryTravelBlocked: block.blocked,
    MandatoryTravelRejectReason: block.reason || '',
    MandatoryTravelPercentMax: block.percentMax || '',
  },
};

const MIN_FULL_JOB_TEXT = 200;

const SOFT_PREFERENCE_ONLY = /\b(preferred|nice to have|highly desirable|desirable|advantageous|a plus|ideally|would be (?:a )?bonus)\b/i;

const DOMAIN_RULES = [
  {
    domainPatterns: [
      /\bigaming\b/i,
      /\bregulated\s+(?:gambling|gaming)\s+markets?\b/i,
      /\bonline\s+(?:gambling|gaming|casino)\b/i,
      /\bgambling\s+brands?\b/i,
    ],
    label: 'iGaming / regulated gambling',
  },
  {
    domainPatterns: [
      /\bclinical\b/i,
      /\bclinical trial\b/i,
      /\bclinical operations\b/i,
      /\bgcp\b/i,
      /\bich\b/i,
    ],
    label: 'clinical',
  },
  {
    domainPatterns: [
      /\bhome\s+care\b/i,
      /\bhealth\s*care\b/i,
      /\bhealthcare\b/i,
      /\belderly\s+care\b/i,
      /\bnursing\s+care\b/i,
      /\bhomecare\b/i,
    ],
    label: 'healthcare / home care',
  },
  {
    domainPatterns: [
      /\bregulated\s+financial\b/i,
      /\bbanking\s+regulatory\b/i,
      /\bpharma(?:ceutical)?\b/i,
      /\bmedtech\b/i,
    ],
    label: 'regulated financial / pharma',
  },
];

const hasMandatoryLanguage = (chunk) => {
  const c = String(chunk || '');
  if (!c.trim()) return false;
  if (SOFT_PREFERENCE_ONLY.test(c) && !/\b(mandatory|required|must have|must possess|essential)\b/i.test(c)) {
    return false;
  }
  return (
    /\b(is\s+)?mandatory\b/i.test(c)
    || /\b(required|must have|must possess|essential requirement|non-negotiable)\b/i.test(c)
    || (/\b(?:minimum|at least)\s+\d+\+?\s*years?\b/i.test(c) && /\b(?:experience|background|track record)\b/i.test(c))
    || /\d+\+?\s*years?[^.]{0,120}\b(?:is\s+)?(?:mandatory|required|essential)\b/i.test(c)
    || /\bproven\s+(?:senior\s+)?(?:leadership\s+)?experience\s+within\b/i.test(c)
  );
};

const hasSpecializedExperienceContext = (chunk) =>
  /\b(?:years?|experience|background|track record|prior|leading|expertise|proven|leadership)\b/i.test(chunk);

const detectMandatorySpecializedDomainBlock = (fullJobText) => {
  const text = String(fullJobText || '').trim();
  if (text.length < MIN_FULL_JOB_TEXT) return { blocked: false, reason: '', domain: '' };

  const chunks = text.split(/[.;\n]/).map((c) => c.trim()).filter((c) => c.length > 20);
  for (const chunk of chunks) {
    if (!hasMandatoryLanguage(chunk) || !hasSpecializedExperienceContext(chunk)) continue;

    for (const rule of DOMAIN_RULES) {
      if (rule.domainPatterns.some((re) => re.test(chunk))) {
        return {
          blocked: true,
          domain: rule.label,
          reason: `Mandatory specialized domain experience: ${rule.label}`,
        };
      }
    }
  }

  return { blocked: false, reason: '', domain: '' };
};

const fullJobText = String($json.FullJobText || '').trim();
const enrichmentOk =
  String($json.EnrichmentStatus || '') === 'OK' && fullJobText.length >= MIN_FULL_JOB_TEXT;
const block = enrichmentOk
  ? detectMandatorySpecializedDomainBlock(fullJobText)
  : { blocked: false, reason: '', domain: '' };

return {
  json: {
    ...$json,
    MandatoryDomainBlocked: block.blocked,
    MandatoryDomainRejectReason: block.reason || '',
    MandatoryDomainLabel: block.domain || '',
  },
};

// Mandatory language evaluated in Pre-PF Eligibility Gate (before Professional Fit).
return {
  json: {
    ...$json,
    MandatoryLanguageBlocked: false,
    MandatoryLanguageRejectReason: '',
    MandatoryLanguageLabel: '',
    MandatoryLanguageGateSkipped: true,
  },
};

// Skip HTTP enrichment when URL/JobUrl is missing or invalid. Keep preview/initial eval only.
const previewScore = Number($json.PreviewScore);
const threshold = Number($json.PreviewScoreThreshold ?? 7);
const passesPreview =
  $json.PreviewPassesThreshold === true
  || (Number.isFinite(previewScore) && previewScore >= threshold);

return {
  json: {
    ...$json,
    PipelineStage: 'NO_URL_PREVIEW_ONLY',
    NeedsEnrichment: false,
    MainRisk: 'Missing job URL; evaluated from email preview only',
    Status: passesPreview ? 'New' : 'Rejected',
    FinalDecision: passesPreview ? 'MONITOR' : 'REJECT_PREVIEW',
    RejectReason: passesPreview ? '' : ($json.RejectReason || 'Preview score below threshold (no URL)'),
    EnrichmentStatus: 'SKIPPED',
    EnrichmentError: 'Missing or invalid job URL; full posting fetch skipped',
    FullJobText: '',
    FullJobTextLength: 0,
    VerifiedScore: '',
    VerifiedRecommendation: '',
    VerifiedRisk: '',
    VerifiedWhyApply: '',
    FinalCV: '',
    VerifiedInterviewProbability: $json.InterviewProbability ?? $json.VerifiedInterviewProbability ?? 0,
    SalaryEstimate: '',
    SalaryTarget: '',
    SalaryConfidence: '',
    SalaryAssumption: '',
    VerifiedPriority: $json.VerifiedPriority || $json.Priority || 'LOW',
    SalaryRange: '',
  },
};

const MIN_FULL_JOB_TEXT = 200;

const SOFT_PREFERENCE_ONLY =
  /\b(preferred|nice to have|highly desirable|desirable|advantageous|a plus|ideally|would be (?:a )?bonus|helpful|beneficial|bonus)\b/i;

const GENERIC_REMOTE_ALLOW = [
  /\bremote\s+europe\b/i,
  /\bremote\s+emea\b/i,
  /\bremote\s+worldwide\b/i,
  /\bremote\s+global\b/i,
