  /\bwithin\s+europe\b/i,
  /\beuropean\s+union\b/i,
];

const COUNTRY_ALIASES = [
  ['united kingdom', 'UK'],
  ['great britain', 'UK'],
  ['england', 'UK'],
  ['uk', 'UK'],
  ['british', 'UK'],
  ['united arab emirates', 'UAE'],
